import { LaravelAuthApi } from "@/infrastructure/auth/LaravelAuthApi";
import { TokenStorage } from "@/infrastructure/auth/TokenStorage";
import { getDeviceId } from "@/utils/deviceId";
import { AuthUser } from "@/domain/auth/AuthUser";

export class TokenRefreshService {
  constructor(private api: LaravelAuthApi) {}

  async refresh(): Promise<AuthUser | null> {
    const { refreshToken } = TokenStorage.load();

    if (!refreshToken) return null;

    const deviceId = getDeviceId();

    const tokens = await this.api.refresh(refreshToken, deviceId);
    TokenStorage.save(tokens);

    return await this.api.me();
  }
}
